+function Profile({ userId }: { userId: string }) {
+  const [user, setUser] = useState<User | null>(null);
+  const [posts, setPosts] = useState<Post[] | null>(null);
+
+  // load the user first
+  useEffect(() => {
+    fetchUser(userId).then(setUser);
+  }, [userId]);
+
+  // then load posts once the user is in state
+  useEffect(() => {
+    if (!user) return;
+    fetchPosts(userId).then(setPosts); // note: keyed by userId, not user.id
+  }, [user, userId]);
+
+  if (!user || !posts) return <Spinner />;
+  return <ProfileView user={user} posts={posts} />;
+}
